components.css:
/* Page navigation shared by the portfolio and its project notes. */
.ds-site-tabs {
  --tab-ink: var(--fg, var(--ink, #1a1a19));
  --tab-muted: var(--muted, var(--secondary, #62625e));
  display: flex;
  align-items: stretch;
  gap: 24px;
  font: 400 12px/1.5 var(--mono, "SFMono-Regular", Consolas, "Liberation Mono", monospace);
}

.ds-site-tabs a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 0 2px;
  border-bottom: 2px solid transparent;
  color: var(--tab-muted);
  text-decoration: none;
  white-space: nowrap;
}

.ds-site-tabs a:hover { color: var(--tab-ink); }
.ds-site-tabs a[aria-current="page"] { color: var(--tab-ink); border-bottom-color: var(--tab-ink); }

@media (max-width: 440px) {
  .ds-site-tabs { gap: 20px; font-size: 11px; }
}
:focus-visible { outline: 2px solid var(--link, #34558f); outline-offset: 5px; }

code, pre { font-family: var(--mono, "SFMono-Regular", Consolas, "Liberation Mono", monospace); }
pre code { font-size: inherit; }
.ds-trace-disclosure { border: 1px solid var(--rule, #d8d8d2); }
.ds-trace-disclosure summary { position: relative; display: flex; align-items: center; gap: 9px; min-height: 44px; padding: 10px 15px; cursor: pointer; list-style: none; font: 12px/1.6 var(--sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif); }
.ds-trace-disclosure summary::-webkit-details-marker { display: none; }
.ds-trace-disclosure summary::before { content: ""; width: 5px; height: 5px; border: solid currentColor; border-width: 1px 1px 0 0; transform: rotate(45deg); margin-right: 3px; flex: none; }
.ds-trace-disclosure[open] summary::before { transform: rotate(135deg); }
.ds-trace-disclosure summary:hover { background: var(--subtle, #f2f2ef); }
.ds-code-language { margin-left: auto; font: 10px/1.5 var(--mono, "SFMono-Regular", Consolas, "Liberation Mono", monospace); color: var(--secondary, #62625e); }
.ds-trace-content { padding: 14px 18px 18px; border-top: 1px solid var(--rule, #d8d8d2); background: var(--subtle, #f2f2ef); }
.ds-example-note { margin: 0 0 14px; font: 12px/1.6 var(--sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif); color: var(--secondary, #62625e); }
pre { margin: 0; overflow-x: auto; color: var(--ink, #1a1a19); font-size: 12px; line-height: 1.8; tab-size: 2; scrollbar-color: var(--rule, #d8d8d2) var(--subtle, #f2f2ef); }
.ds-trace-disclosure { color: var(--ink, #1a1a19); }
:focus-visible { outline: 2px solid var(--link, #34558f); outline-offset: 5px; }

.ds-pipeline { margin: 35px 0 0; padding: 26px 0 22px; border-top: 1px solid var(--rule, #d8d8d2); border-bottom: 1px solid var(--rule, #d8d8d2); }
.ds-pipeline-flow { display: grid; grid-template-columns: minmax(0, 1fr) 52px minmax(0, 1fr) 52px minmax(0, 1fr); align-items: center; }
.ds-pipeline-stage { min-width: 0; text-align: center; }
.ds-stage-drawing { display: block; margin: 0 auto 13px; color: var(--secondary, #62625e); }
.ds-pipeline-stage h3 { font: 500 13px/1.5 var(--sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif); margin: 0 0 3px; }
.ds-pipeline-stage p { font: 11.5px/1.6 var(--sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif); color: var(--secondary, #62625e); margin: 0; }
.ds-stage-notation { display: block; margin-top: 8px; font: 10.5px/1.5 var(--mono, "SFMono-Regular", Consolas, "Liberation Mono", monospace); color: var(--secondary, #62625e); }
.ds-pipeline-arrow { color: var(--secondary, #62625e); margin-top: -43px; width: 100%; }
figcaption { margin-top: 23px; text-align: center; color: var(--secondary, #62625e); font-size: 12.5px; line-height: 1.6; }
.ds-figure-number { font-style: italic; color: var(--ink, #1a1a19); }


@media (max-width: 440px) {
  .ds-pipeline-flow { grid-template-columns: minmax(0, 1fr); gap: 8px; justify-items: center; }
  .ds-pipeline-stage { width: 100%; display: grid; grid-template-columns: 70px minmax(0, 1fr); column-gap: 17px; padding: 0 14px; text-align: left; }
  .ds-stage-drawing { grid-column: 1; grid-row: 1 / 4; margin: 0; align-self: center; }
  .ds-pipeline-stage h3 { font-size: 13px; }
  .ds-pipeline-stage p { font-size: 11px; }
  .ds-stage-notation { font-size: 10px; margin-top: 4px; }
  .ds-pipeline-arrow { height: 25px; width: 25px; margin: 1px 0 1px 0; transform: rotate(90deg); }
  .ds-pipeline { padding-top: 23px; }
}
.ds-pipeline { color: var(--ink, #1a1a19); font-family: var(--serif, Georgia, "Times New Roman", serif); }

.ds-visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
.ds-implementation-table { width: 100%; margin: 22px 0 17px; border-collapse: collapse; text-align: left; }
.ds-implementation-table th, .ds-implementation-table td { padding: 14px 0; vertical-align: top; border-bottom: 1px solid var(--rule, #d8d8d2); }
.ds-implementation-table thead th { padding-top: 0; padding-bottom: 9px; color: var(--secondary, #62625e); font: 11px/1.5 var(--mono, "SFMono-Regular", Consolas, "Liberation Mono", monospace); }
.ds-implementation-table tbody th { width: 37%; padding-right: 24px; font: 400 14px/1.6 var(--sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif); }
.ds-implementation-table td { font: 13px/1.6 var(--sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif); }
.ds-table-note { display: inline-block; margin-top: 3px; color: var(--secondary, #62625e); font-size: 12px; }
.ds-implementation-table { color: var(--ink, #1a1a19); }
